"use client";
import {
  RiCursorLine,
  RiEyeLine,
  RiCoinsLine,
  RiUserFollowLine,
  RiSearchLine,
  RiGroupLine,
  RiChatSmile2Line,
  RiBriefcaseLine,
  RiMailLine,
  RiShakeHandsLine,
  RiGlobalLine,
  RiMegaphoneLine,
} from "@remixicon/react";
import { AreaChartCard } from "../charts/area-chart-card";
import { BarListCard, type BarListTab } from "../charts/bar-list-card";
import { ComboChartCard } from "../charts/combo-chart-card";
import { FunnelChartCard } from "../charts/funnel-chart-card";
import { RadialChartCard } from "../charts/radial-chart-card";
import { StatCards } from "../dashboard/stat-cards";
import { type DashboardTemplateProps, DataDashboard } from "./data-dashboard";
import {
  MARKETING_FUNNEL_RANGES,
  MARKETING_SPEND_RANGES,
  MARKETING_COMBO_RANGES,
  MARKETING_VISITORS_RANGES,
} from "./marketing-chart-data";
const CHANNEL_NAMES = [
  "Search ads",
  "Social ads",
  "Community ads",
  "Professional ads",
  "Email",
  "Affiliates",
  "Referral",
];
const CHANNEL_ICONS = [
  RiSearchLine,
  RiGroupLine,
  RiChatSmile2Line,
  RiBriefcaseLine,
  RiMailLine,
  RiShakeHandsLine,
  RiGlobalLine,
];
export const MARKETING_CHANNEL_TABS: BarListTab[] = [
  {
    id: "channels",
    label: "Channels",
    items: [24600, 15800, 8700, 5350, 4650, 2350, 1550].map((value, i) => {
      const Icon = CHANNEL_ICONS[i]!;
      return { label: CHANNEL_NAMES[i]!, value, icon: <Icon className="size-4" /> };
    }),
  },
  {
    id: "campaigns",
    label: "Campaigns",
    items: [
      "Brand search",
      "Spring launch",
      "Cart retargeting",
      "Competitor keywords",
      "Founder story video",
      "Newsletter promo",
      "Lookalike broad",
    ].map((label, i) => ({ label, value: [23100, 19700, 14050, 9650, 7400, 5600, 4300][i]! })),
  },
  {
    id: "pages",
    label: "Landing pages",
    items: [
      "/pricing",
      "/templates",
      "/",
      "/components",
      "/blog/launch-week",
      "/docs/quickstart",
    ].map((label, i) => ({ label, value: [26200, 20900, 16800, 11200, 7050, 3900][i]! })),
  },
];
export interface MarketingDashboardProps extends DashboardTemplateProps {
  channelTabs?: BarListTab[];
}
export function MarketingDashboard({
  channelTabs = MARKETING_CHANNEL_TABS,
  ...props
}: MarketingDashboardProps = {}) {
  return (
    <DataDashboard
      icon={RiMegaphoneLine}
      tableLayout="fluid"
      tableChannels={channelTabs
        .find((tab) => tab.id === "channels")
        ?.items.map((item) => item.label)}
      enableRecordCreation={false}
      {...props}
      kind="marketing"
      title="Marketing"
      selected="marketing"
      action="New campaign"
    >
      <StatCards
        className="max-sm:grid-cols-1"
        stats={[
          {
            icon: RiCoinsLine,
            label: "Ad spend",
            value: "$24,380",
            delta: "+8.4%",
            deltaColor: "lime",
          },
          {
            icon: RiEyeLine,
            label: "Impressions",
            value: "1.94M",
            delta: "+12.6%",
            deltaColor: "lime",
          },
          {
            icon: RiUserFollowLine,
            label: "Conversions",
            value: "1,286",
            delta: "+5.2%",
            deltaColor: "lime",
          },
          {
            icon: RiCursorLine,
            label: "Cost per click",
            value: "$1.24",
            delta: "-3.1%",
            deltaColor: "rose",
          },
        ]}
      />
      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        <FunnelChartCard
          title="Acquisition funnel"
          ranges={MARKETING_FUNNEL_RANGES}
          defaultRange="month"
          className="h-[329px]"
          format={(n) =>
            n.toLocaleString("en-US", { notation: "compact", maximumFractionDigits: 1 })
          }
        />
        <RadialChartCard
          title="Spend by channel"
          variant="stacked"
          ranges={MARKETING_SPEND_RANGES}
          defaultRange="month"
          format={(n) => `$${n.toLocaleString("en-US")}`}
        />
        <BarListCard
          className="md:col-span-2 xl:col-span-1"
          metricLabel="Sessions"
          tabs={channelTabs}
        />
      </div>
      <div className="grid gap-4 xl:grid-cols-2">
        <ComboChartCard
          className="h-auto"
          title="Ad spend"
          ranges={MARKETING_COMBO_RANGES}
          bar={{
            key: "spend",
            label: "Ad spend",
            format: (n) =>
              `$${n.toLocaleString("en-US", { notation: "compact", maximumFractionDigits: 1 })}`,
          }}
          line={{ key: "roas", label: "ROAS", format: (n) => `${n.toFixed(1)}x` }}
        />
        <AreaChartCard
          className="h-auto"
          title="Visitors"
          ranges={MARKETING_VISITORS_RANGES}
          series={[
            { key: "organic", label: "Organic" },
            { key: "paid", label: "Paid" },
            { key: "social", label: "Social" },
          ]}
        />
      </div>
    </DataDashboard>
  );
}
